tape( 'if called without arguments, the method returns a new tuple over the same underlying buffer', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 10, 20, 30 ] );

	out = p.subtuple();

	t.notEqual( out, p, 'returns expected value' );
	t.strictEqual( out.buffer, p.buffer, 'returns expected value' );
	t.deepEqual( out.fields, [ 'x', 'y', 'z' ], 'returns expected value' );
	t.strictEqual( out[ 0 ], 10, 'returns expected value' );
	t.strictEqual( out[ 1 ], 20, 'returns expected value' );
	t.strictEqual( out[ 2 ], 30, 'returns expected value' );
	t.end();
});

tape( 'if provided one argument, the method returns a subtuple starting from a specified index', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z', 'w' ] );
	p = new Point( [ 1, 2, 3, 4 ] );

	out = p.subtuple( 1 );

	t.strictEqual( out.buffer, p.buffer, 'returns expected value' );
	t.deepEqual( out.fields, [ 'y', 'z', 'w' ], 'returns expected value' );
	t.strictEqual( out[ 0 ], 2, 'returns expected value' );
	t.strictEqual( out[ 1 ], 3, 'returns expected value' );
	t.strictEqual( out[ 2 ], 4, 'returns expected value' );
	t.end();
});

tape( 'if provided two arguments, the method returns a subtuple from a start index (inclusive) to an end index (exclusive)', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z', 'w' ] );
	p = new Point( [ 1, 2, 3, 4 ] );

	out = p.subtuple( 1, 3 );

	t.strictEqual( out.buffer, p.buffer, 'returns expected value' );
	t.deepEqual( out.fields, [ 'y', 'z' ], 'returns expected value' );
	t.strictEqual( out[ 0 ], 2, 'returns expected value' );
	t.strictEqual( out[ 1 ], 3, 'returns expected value' );
	t.end();
});

tape( 'the method supports negative indices', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z', 'w' ] );
	p = new Point( [ 1, 2, 3, 4 ] );

	out = p.subtuple( -3, -1 );

	t.strictEqual( out.buffer, p.buffer, 'returns expected value' );
	t.deepEqual( out.fields, [ 'y', 'z' ], 'returns expected value' );
	t.strictEqual( out[ 0 ], 2, 'returns expected value' );
	t.strictEqual( out[ 1 ], 3, 'returns expected value' );
	t.end();
});

tape( 'the method clamps a very negative begin index to zero', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	out = p.subtuple( -100 );

	t.strictEqual( out.buffer, p.buffer, 'returns expected value' );
	t.deepEqual( out.fields, [ 'x', 'y', 'z' ], 'returns expected value' );
	t.strictEqual( out[ 0 ], 1, 'returns expected value' );
	t.strictEqual( out[ 1 ], 2, 'returns expected value' );
	t.strictEqual( out[ 2 ], 3, 'returns expected value' );
	t.end();
});

tape( 'the method clamps a very negative end index to zero', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	out = p.subtuple( 0, -100 );

	t.strictEqual( out.length, 0, 'returns expected value' );
	t.deepEqual( out.fields, [], 'returns expected value' );
	t.end();
});

tape( 'the method clamps an end index which exceeds the tuple length', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	out = p.subtuple( 1, 100 );

	t.strictEqual( out.buffer, p.buffer, 'returns expected value' );
	t.deepEqual( out.fields, [ 'y', 'z' ], 'returns expected value' );
	t.strictEqual( out[ 0 ], 2, 'returns expected value' );
	t.strictEqual( out[ 1 ], 3, 'returns expected value' );
	t.end();
});

tape( 'the method returns an empty tuple if a resolved beginning index exceeds a resolved ending index', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z', 'w' ] );
	p = new Point( [ 1, 2, 3, 4 ] );

	out = p.subtuple( 2, 0 );

	t.strictEqual( out.length, 0, 'returns expected value' );
	t.deepEqual( out.fields, [], 'returns expected value' );
	t.end();
});

tape( 'the subtuple shares the same underlying buffer (mutations are shared)', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 10, 20, 30 ] );

	out = p.subtuple( 1 );
	out[ 0 ] = 99;

	t.strictEqual( p[ 1 ], 99, 'returns expected value' );
	t.end();
});
